local function section(name, fn)
    local ok, err = xpcall(fn, debug.traceback)
    if not ok then
        _G.__CW_AE_ERR = _G.__CW_AE_ERR or {}
        _G.__CW_AE_ERR[name] = err
        notify(name .. __T[" tab failed to load"])
    end
end
section(__T["Suggestions"], function()
    local Tab = Window:AddTab(__T["Suggestions"], "message-square")
    local FEEDBACK_URL = "https://v0-secure-discord-proxy.vercel.app/api/v2sender"
    local _request = request or (syn and syn.request) or http_request
    local okId, cid = pcall(function() return game:GetService("RbxAnalyticsService"):GetClientId() end)
    local HWID = (okId and type(cid) == "string" and cid ~= "") and cid or tostring(lp.UserId)
    local ERR = {
        empty = "The message is empty.", no_links = "Links are not allowed.", too_long = "Too long (500 max).",
        rate_limited = "You reached the limit. Try again later.", network = "Network error.",
        no_request = "Your executor cannot send requests.", bad_response = "Unexpected server response.",
        unreachable = "Your executor cannot reach the server.",
    }
    local function send(ftype, msg)
        if not _request then return false, "no_request" end
        local ok, res = pcall(function()
            return _request({ Url = FEEDBACK_URL, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode({ type = ftype, message = msg, hwid = HWID, placeId = tostring(game.PlaceId), username = lp.Name, version = CONFIG.VERSION }) })
        end)
        if not ok or type(res) ~= "table" then return false, (type(res) == "string") and "unreachable" or "network" end
        local code = res.StatusCode or res.status_code or res.Status or res.status
        if type(code) == "number" and code ~= 200 and code ~= 201 and code ~= 204 then return false, "http_" .. code end
        local dok, data = pcall(function() return HttpService:JSONDecode(res.Body or res.body or "") end)
        if not dok or type(data) ~= "table" then return false, "bad_response" end
        if data.success == true then return true end
        return false, tostring(data.error or "unknown")
    end
    local FG = Tab:AddLeftGroupbox(__T["Suggestions / Help"], "message-square")
    FG:AddDropdown("FeedbackType", { Text = __T["Type"], Values = { "Suggestion", "Bug", "Help" }, Default = "Suggestion" })
    FG:AddInput("FeedbackMsg", { Default = "", Numeric = false, Finished = false, ClearTextOnFocus = false, Text = __T["Message"], Placeholder = __T["500 chars max, no links"] })
    local status = FG:AddLabel("", true)
    local last = 0
    FG:AddButton({ Text = __T["Send"], Func = function()
        if tick() - last < 20 then setText(status, string.format(__T["Wait %ds"], math.ceil(20 - (tick() - last)))); return end
        local msg = tostring(val("FeedbackMsg", "")):gsub("^%s*(.-)%s*$", "%1")
        if msg == "" then setText(status, ERR.empty); return end
        if #msg > 500 then setText(status, ERR.too_long); return end
        local low = msg:lower()
        if low:find("http", 1, true) or low:find("discord.gg", 1, true) or low:find("www.", 1, true) or low:find(".gg/", 1, true) then setText(status, ERR.no_links); return end
        setText(status, __T["Sending..."])
        task.spawn(function()
            local ok, err = send(tostring(val("FeedbackType", "Suggestion")):lower(), msg)
            if ok then last = tick(); setText(status, __T["Sent. Thank you!"]); pcall(function() Opt.FeedbackMsg:SetValue("") end)
            else setText(status, ERR[err] or (__T["Failed: "] .. tostring(err))) end
        end)
    end })
    FG:AddLabel(__T["Max 3 messages per hour."], true)
    local HG = Tab:AddLeftGroupbox(__T["Quick Start"], "life-buoy")
    HG:AddLabel(__T["1. Farm: Auto Train for chakra."], true)
    HG:AddLabel(__T["2. Farm: Auto Stages for wins."], true)
    HG:AddLabel(__T["3. Progress: rebirth, eyes, pets."], true)
    HG:AddLabel(__T["4. Rewards claim themselves."], true)
    if CONFIG.DISCORD_INVITE ~= "" then
        HG:AddButton({ Text = __T["Copy Discord Invite"], Func = function() pcall(setclipboard, CONFIG.DISCORD_INVITE); notify(__T["Discord link copied"]) end })
    end
    local CG = Tab:AddRightGroupbox(__T["Changelog"], "list")
    CG:AddLabel('<font color="#f5c542"><b>2026-10-30  v1.0</b></font>', true)
    for _, l in ipairs({ __T["+ Auto train 12/s"], __T["+ Best train spot"], __T["+ Auto stages"], __T["+ Auto win pads"], __T["+ Auto skills"], __T["+ Auto boss (next upd)"], __T["+ Auto rebirth"], __T["+ Auto unlock eyes"], __T["+ Equip best eye"], __T["+ Auto hatch"], __T["+ Equip best pets"], __T["+ Delete weak pets"], __T["+ Equip best aura"], __T["+ Next world"], __T["+ All codes"], __T["+ Gifts, exit bonus"], __T["+ Daily, quests"], __T["+ Train bubbles"], __T["+ Skip revive popup"], __T["+ Wins per hour"] }) do CG:AddLabel(l, true) end
end)
