            setText(UI.s3, string.format(__T["Wins/h %s · Runs %d%s · Hatched %d"], wph >= 1000 and string.format("%.1fk", wph / 1000) or tostring(math.floor(wph)), S.runs, (S.lost or 0) > 0 and string.format(__T[" (%d lost)"], S.lost) or "", S.hatched))
            local g = (os.clock() - S.gmsgAt < 8 and S.gmsg ~= "") and S.gmsg or ((os.clock() - S.msgAt < 8) and S.msg or "")
            setText(UI.s4, g ~= "" and (__T["Game: "] .. g) or "")
            local _, sp = F.trainSpot()
            setText(UI.tr, sp and (__T["Spot: "] .. tostring(sp.name) .. __T[" x"] .. tostring(sp.mult)) or "")
            local w = M.world()
